package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class RewardsEntryBudgetTest {
 private static final String NONCE="0".repeat(32);
 @Test public void runMustPrecedeEveryOtherSlot(){var b=new RewardsEntryBudget((s,n)->{},NONCE);for(var s:RewardsEntryBudget.Slot.values())if(s!=RewardsEntryBudget.Slot.RUN_1)assertThrows(SecurityException.class,()->b.burn(s));}
 @Test public void allSlotsAreOnceOnly()throws Exception{List<RewardsEntryBudget.Slot> writes=new ArrayList<>();var b=new RewardsEntryBudget((s,n)->writes.add(s),NONCE);for(var s:RewardsEntryBudget.Slot.values()){b.burn(s);assertThrows(SecurityException.class,()->b.burn(s));}assertEquals(4,writes.size());}
 @Test public void uncertainWritePoisonsRemainingSlots()throws Exception{var b=new RewardsEntryBudget((s,n)->{if(s==RewardsEntryBudget.Slot.NAV_1)throw new java.io.IOException();},NONCE);b.burn(RewardsEntryBudget.Slot.RUN_1);b.burn(RewardsEntryBudget.Slot.PREPARE_1);assertThrows(java.io.IOException.class,()->b.burn(RewardsEntryBudget.Slot.NAV_1));assertTrue(b.uncertain());assertFalse(b.confirmed(RewardsEntryBudget.Slot.NAV_1));assertThrows(SecurityException.class,()->b.burn(RewardsEntryBudget.Slot.UI_READ_1));assertThrows(SecurityException.class,()->b.burn(RewardsEntryBudget.Slot.NAV_1));}
 @Test public void directTemplateMaySkipNavigation()throws Exception{var b=new RewardsEntryBudget((s,n)->{},NONCE);b.burn(RewardsEntryBudget.Slot.RUN_1);b.burn(RewardsEntryBudget.Slot.UI_READ_1);assertFalse(b.confirmed(RewardsEntryBudget.Slot.PREPARE_1));assertThrows(SecurityException.class,()->b.burn(RewardsEntryBudget.Slot.PREPARE_1));}
 @Test public void preparedCannotReadWithoutNavigationBurn()throws Exception{var b=new RewardsEntryBudget((s,n)->{},NONCE);b.burn(RewardsEntryBudget.Slot.RUN_1);b.burn(RewardsEntryBudget.Slot.PREPARE_1);assertThrows(SecurityException.class,()->b.burn(RewardsEntryBudget.Slot.UI_READ_1));}
 @Test public void fiveSecondsStartsAtReceivedReceipt(){assertFalse(RewardsEntryBudget.waitSatisfied(1000,5999));assertTrue(RewardsEntryBudget.waitSatisfied(1000,6000));assertFalse(RewardsEntryBudget.waitSatisfied(-1,9000));assertFalse(RewardsEntryBudget.waitSatisfied(1000,999));}
 @Test public void historicalWindowsUnchanged(){assertEquals(1794474000000L,ReadOnlyCheckpoint.UI_STRUCTURE_V45.starts());assertEquals(1794477600000L,ReadOnlyCheckpoint.UI_STRUCTURE_V45.expires());var p=ReadOnlyCheckpoint.REWARDS_ENTRY_V46;assertEquals(1794476700000L,p.starts());assertEquals(1794483900000L,p.expires());assertFalse(p.admissionCurrent(p.expires()-180000));assertEquals(-1,p.sourceTask());assertNotEquals(p.directory(),ReadOnlyCheckpoint.UI_STRUCTURE_V45.directory());}
}
